'use strict';

const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const money = value => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(value || 0));
const safe = value => String(value ?? '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
let dashboardData = null;

const modal = $('#auth-modal');
function openAuth(tab = 'login') { modal.classList.add('open'); modal.setAttribute('aria-hidden', 'false'); switchAuth(tab); }
function closeAuth() { modal.classList.remove('open'); modal.setAttribute('aria-hidden', 'true'); }
function switchAuth(tab) {
  $$('.auth-tabs button').forEach(b => b.classList.toggle('active', b.dataset.tab === tab));
  $('#login-form').classList.toggle('hidden', tab !== 'login');
  $('#register-form').classList.toggle('hidden', tab !== 'register');
  $('#auth-title').innerHTML = tab === 'login' ? 'SELAMAT DATANG<br><em>KEMBALI.</em>' : 'MULAI KISAH<br><em>BARUMU.</em>';
  $('#auth-desc').textContent = tab === 'login' ? 'Masuk untuk mengelola seluruh kehidupan karaktermu.' : 'Satu akun UCP untuk semua character milikmu.';
  $('#auth-message').innerHTML = '';
}
function toast(text) { const el = $('#toast'); el.textContent = text; el.classList.add('show'); setTimeout(() => el.classList.remove('show'), 2400); }
function syncAuthUI(authenticated){$$('.open-auth').forEach(b=>{b.textContent=authenticated?'Buka UCP':'Masuk';b.classList.toggle('hidden',authenticated)});$$('.open-register').forEach(b=>{if(!b.dataset.guestLabel)b.dataset.guestLabel=b.innerHTML;b.innerHTML=authenticated?'Buka Dashboard <span>→</span>':b.dataset.guestLabel});$('#public-logout').classList.toggle('hidden',!authenticated);$('#public-profile').classList.toggle('hidden',!authenticated);$('.nav-register').classList.toggle('hidden',authenticated);document.body.classList.toggle('is-authenticated',authenticated);if(authenticated&&dashboardData){const u=dashboardData.ucp;$('#public-avatar').textContent=u.username[0].toUpperCase();$('#public-username').textContent=u.username;$('#public-role').textContent=u.isAdmin?`ADMIN LEVEL ${u.admin}`:'UCP VERIFIED'}}
async function logoutSession(){await api('/api/auth/logout',{method:'POST'}).catch(()=>{});dashboardData=null;syncAuthUI(false);showPublicRoute('/');toast('Kamu telah keluar dari UCP')}
function message(text, success = false) { $('#auth-message').innerHTML = `<div class="alert ${success ? 'success' : ''}">${safe(text)}</div>`; }
async function api(url, options) {
  const res = await fetch(url, { headers: { 'Content-Type': 'application/json' }, ...options });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data.error || 'Permintaan gagal. Coba kembali.');
  return data;
}

$$('.open-auth').forEach(b => b.addEventListener('click', () => dashboardData ? showDashboard() : openAuth('login')));
$$('.open-register').forEach(b => b.addEventListener('click', () => dashboardData ? showDashboard() : openAuth('register')));
$('.modal-close').addEventListener('click', closeAuth);
modal.addEventListener('click', e => { if (e.target === modal) closeAuth(); });
document.addEventListener('keydown', e => { if (e.key === 'Escape') closeAuth(); });
$$('.auth-tabs button').forEach(b => b.addEventListener('click', () => switchAuth(b.dataset.tab)));

$('#login-form').addEventListener('submit', async e => {
  e.preventDefault(); const button = $('button[type=submit]', e.currentTarget); button.disabled = true; button.textContent = 'Memeriksa...';
  try { const form = new FormData(e.currentTarget); await api('/api/auth/login', { method:'POST', body:JSON.stringify(Object.fromEntries(form)) }); dashboardData = await api('/api/me'); syncAuthUI(true); const intended=location.pathname==='/admin'?'admin':location.pathname.startsWith('/ucp/')?location.pathname.split('/')[2]:'overview'; showDashboard(intended); closeAuth(); }
  catch (err) { message(err.message); } finally { button.disabled = false; button.innerHTML = 'Masuk ke UCP <span>→</span>'; }
});
$('#register-form').addEventListener('submit', async e => {
  e.preventDefault(); const button = $('button[type=submit]', e.currentTarget); button.disabled = true; button.textContent = 'Membuat akun...';
  try { const form = new FormData(e.currentTarget); const result = await api('/api/auth/register', { method:'POST', body:JSON.stringify(Object.fromEntries(form)) }); $('#auth-message').innerHTML=`<div class="registration-pin-result"><span>UCP BERHASIL DIBUAT</span><p>${safe(result.message)}</p><small>PIN AKTIVASI IN-GAME</small><strong>${safe(result.gamePin)}</strong><button type="button" class="copy-game-pin" data-pin="${safe(result.gamePin)}">Salin PIN</button><em>Simpan PIN ini. Masukkan di server SA-MP ketika diminta, lalu gunakan <b>/verify ${safe(result.verifyCode)}</b> pada Discord.</em></div>`; e.currentTarget.reset(); }
  catch (err) { message(err.message); } finally { button.disabled = false; button.innerHTML = 'Buat Akun UCP <span>→</span>'; }
});

$$('[data-copy]').forEach(b => b.addEventListener('click', async () => { try { await navigator.clipboard.writeText(b.dataset.copy); } catch {} b.textContent = 'TERSALIN ✓'; toast('IP server disalin'); setTimeout(() => b.textContent = 'SALIN IP', 1800); }));
document.addEventListener('click',async e=>{const button=e.target.closest('.copy-game-pin');if(!button)return;try{await navigator.clipboard.writeText(button.dataset.pin);button.textContent='PIN TERSALIN ✓';toast('PIN in-game berhasil disalin')}catch{toast('Salin PIN secara manual')}});
$('#play-trailer').addEventListener('click', () => toast('Trailer Hope Pride segera hadir.'));

const publicRoutes={ '/portal':'portal','/forums':'forums','/directory':'city','/guide':'guide' };
function setLocation(path, replace=false){if(location.pathname===path)return;(replace?history.replaceState:history.pushState).call(history,null,'',path)}
function showDashboard(view='overview', updateHistory=true) {
  if(!dashboardData)return openAuth('login');
  if(view==='admin'&&!dashboardData.ucp.isAdmin&&Number(dashboardData.ucp.admin||0)<1){toast('Akses khusus administrator');view='overview'}
  $('#public-site').classList.add('hidden');$('footer').classList.add('hidden');$('.nav').classList.add('hidden');$('.server-notice').classList.add('hidden');$('#dashboard').classList.remove('hidden');document.body.classList.remove('subpage');
  const u=dashboardData.ucp;$('#account-name').textContent=u.username;$('#avatar-letter').textContent=u.username[0].toUpperCase();$('#admin-nav').classList.toggle('hidden',!u.isAdmin&&Number(u.admin||0)<1);
  $$('#dash-nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===view));document.title=`${titleMap[view]} — Hope Pride UCP`;renderView(view);if(updateHistory)setLocation(view==='admin'?'/admin':view==='overview'?'/ucp':`/ucp/${view}`);window.scrollTo(0,0);
}
function showPublicRoute(path='/',updateHistory=true){
  $('#dashboard').classList.add('hidden');$('#public-site').classList.remove('hidden');$('footer').classList.remove('hidden');$('.nav').classList.remove('hidden');$('.server-notice').classList.remove('hidden');
  const sectionId=publicRoutes[path];$$('#public-site > section').forEach(section=>section.classList.toggle('route-hidden',Boolean(sectionId)&&section.id!==sectionId));document.body.classList.toggle('subpage',Boolean(sectionId));
  $$('.nav-links [data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===path));const pageTitles={'/':'Hope Pride Roleplay','/portal':'Community Portal — Hope Pride','/forums':'Forums — Hope Pride','/directory':'Direktori Kota — Hope Pride','/guide':'Panduan — Hope Pride'};document.title=pageTitles[path]||pageTitles['/'];if(updateHistory)setLocation(path);window.scrollTo(0,0);
}
function handleRoute(updateHistory=false){const path=location.pathname.replace(/\/$/,'')||'/';if(path==='/admin')return dashboardData?showDashboard('admin',updateHistory):(showPublicRoute('/',false),openAuth('login'));if(path==='/ucp'||path.startsWith('/ucp/')){const view=path.split('/')[2]||'overview';return dashboardData?showDashboard(titleMap[view]?view:'overview',updateHistory):(showPublicRoute('/',false),openAuth('login'))}return showPublicRoute(publicRoutes[path]?path:'/',updateHistory)}
$('#back-site').addEventListener('click',()=>showPublicRoute('/'));
$('#logout').addEventListener('click',logoutSession);$('#public-logout').addEventListener('click',logoutSession);
$('#dash-nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)showDashboard(b.dataset.view)});
document.addEventListener('click',e=>{const link=e.target.closest('[data-route]');if(!link)return;if(link.origin&&link.origin!==location.origin)return;e.preventDefault();const path=link.dataset.route;if(path==='/ucp')return dashboardData?showDashboard():openAuth('login');showPublicRoute(path)});
window.addEventListener('popstate',()=>handleRoute(false));

const titleMap = { overview:'Ringkasan Akun', characters:'Character IC', vehicles:'Kendaraan', properties:'Properti', inventory:'Inventori', businesses:'Bisnis', salary:'Riwayat Gaji', progress:'Skill & Koleksi', life:'Life Hub', requestcs:'Request Character Story', settings:'Pengaturan UCP', admin:'Admin Panel' };
function renderView(view) {
  $('#view-title').textContent = titleMap[view]; const el = $('#dash-content');
  if (view === 'overview') return renderOverview(el);
  if (view === 'characters') return renderCharacters(el);
  if (view === 'vehicles') return renderAssets(el, 'vehicles');
  if (view === 'properties') return renderAssets(el, 'properties');
  if (view === 'businesses') return renderBusinesses(el);
  if (view === 'inventory') return renderInventory(el);
  if (view === 'salary') return renderSalary(el);
  if (view === 'progress') return renderProgress(el);
  if (view === 'life') return renderLifeHub(el);
  if (view === 'requestcs') return renderRequestCS(el);
  if (view === 'settings') return renderSettings(el);
  if (view === 'admin') return renderAdmin(el);
}
function charRow(c) { return `<div class="character-row"><div class="char-avatar">${safe(c.name.split('_').map(x=>x[0]).join('').slice(0,2))}</div><div class="row-main"><b>${safe(c.name.replace('_',' '))}</b><small>Level ${c.level} • ${c.hours} jam bermain • ${safe(c.faction)}</small></div><div class="row-value"><b>${money(c.money + c.bank)}</b><small>Total kekayaan</small></div></div>`; }
function renderOverview(el) {
  const d=dashboardData, chars=d.characters, primary=chars[0];
  el.innerHTML=`<div class="welcome"><div><h1>Selamat datang, <em>${safe(d.ucp.username)}.</em></h1><p>Seluruh data tersinkron langsung dengan server game.</p></div><span class="verified-badge">✓ &nbsp; UCP TERVERIFIKASI</span></div>
  <div class="metrics"><div class="metric"><small>CHARACTER IC</small><b>${chars.length}</b></div><div class="metric"><small>KENDARAAN</small><b>${d.vehicles.length}</b></div><div class="metric"><small>PROPERTI / BISNIS</small><b>${d.properties.length} / ${d.businesses.length}</b></div><div class="metric"><small>TOTAL ASET</small><b>${money(chars.reduce((a,c)=>a+Number(c.money)+Number(c.bank),0))}</b></div></div>
  <div class="game-pin-card"><div class="pin-icon">⌗</div><div><small>PIN AKTIVASI IN-GAME</small><strong>${safe(d.ucp.gamePin||'Belum tersedia')}</strong><p>Gunakan PIN ini saat server SA-MP meminta aktivasi UCP. PIN dibaca langsung dari <code>ucp.verifycode</code>.</p></div><button class="copy-game-pin" data-pin="${safe(d.ucp.gamePin||'')}">SALIN PIN</button></div>
  <div class="panel-grid"><div class="panel"><div class="panel-head"><h3>CHARACTER MILIKMU</h3><button data-jump="characters">LIHAT SEMUA →</button></div>${chars.length?chars.map(charRow).join(''):'<div class="empty">Belum ada character IC.</div>'}</div>
  <div class="panel"><div class="panel-head"><h3>KONDISI CHARACTER UTAMA</h3><span></span></div>${primary?`<div class="status-bars">${bar('Health',primary.health)}${bar('Armour',primary.armour)}${bar('Hunger',primary.hunger)}${bar('Energy',primary.energy)}</div>`:'<div class="empty">Tidak ada data.</div>'}</div></div>`;
  $$('[data-jump]',el).forEach(b=>b.addEventListener('click',()=>{const target=$(`[data-view="${b.dataset.jump}"]`);target.click()}));
}
function bar(name,val){const n=Math.max(0,Math.min(100,Number(val)));return `<div><div class="status-label"><span>${name}</span><b>${n}%</b></div><div class="bar"><i style="width:${n}%"></i></div></div>`}
function renderCharacters(el){const c=dashboardData.characters;el.innerHTML=`<div class="welcome"><div><h1>Character <em>In-Character.</em></h1><p>Profil dan perkembangan seluruh character yang terhubung ke UCP.</p></div></div><div class="data-grid">${c.map(x=>`<article class="data-card"><span class="symbol">♙</span><h3>${safe(x.name.replace('_',' '))}</h3><p>Level ${x.level} • ${x.hours} jam • ${safe(x.job)}</p><div class="price">${safe(x.faction)} — Rank ${x.factionRank}</div><p>Terakhir masuk: ${safe(x.lastLogin)}</p></article>`).join('')||'<div class="empty">Belum ada character.</div>'}</div>`}
function renderAssets(el,type){const isVeh=type==='vehicles',items=dashboardData[type];el.innerHTML=`<div class="welcome"><div><h1>${isVeh?'Garasi':'Daftar'} <em>${isVeh?'Kendaraan':'Properti'}.</em></h1><p>Data kepemilikan tersinkron dengan database server.</p></div></div><div class="data-grid">${items.map(x=>isVeh?`<article class="data-card"><span class="symbol">◇</span><h3>${safe(x.name)}</h3><p>${safe(x.owner)} • Model ${x.model} • ID #${x.id}</p><div class="price">Plat ${safe(x.plate||'-')}</div><p>Fuel ${Math.round(x.fuel)}% • ${x.locked?'Terkunci':'Terbuka'}</p></article>`:`<article class="data-card"><span class="symbol">⌂</span><h3>${safe(x.address)}</h3><p>${safe(x.owner)} • Property #${x.id}</p><div class="price">${money(x.price)}</div><p>${x.locked?'Terkunci':'Terbuka'}</p></article>`).join('')||`<div class="empty">Belum ada ${isVeh?'kendaraan':'properti'}.</div>`}</div>`}
function renderBusinesses(el){const items=dashboardData.businesses||[];el.innerHTML=`<div class="welcome"><div><h1>Bisnis <em>Milikmu.</em></h1><p>Kelola informasi warung, toko umum, toko pakaian, dan usaha lainnya.</p></div></div><div class="data-grid">${items.map(x=>`<article class="data-card business-owned"><span class="symbol">${x.type===1?'☕':x.type===3?'♙':'▦'}</span><h3>${safe(x.name)}</h3><p>${safe(x.typeName)} • Business #${x.id}</p><div class="price">Saldo ${money(x.money)}</div><p>Produk ${x.prod} • ${x.locked?'Tutup / Terkunci':'Buka'} • Restock ${x.restock?'Aktif':'Normal'}</p></article>`).join('')||'<div class="empty">Belum memiliki bisnis.</div>'}</div>`}
function renderInventory(el){const items=dashboardData.inventory;el.innerHTML=`<div class="welcome"><div><h1>Inventori <em>Character.</em></h1><p>Ringkasan item dari seluruh character dalam satu akun.</p></div></div><div class="panel"><div class="panel-head"><h3>SEMUA ITEM</h3><span></span></div>${items.map(x=>`<div class="inventory-row"><div class="char-avatar">▦</div><div class="row-main"><b>${safe(x.item)}</b><small>Item tersimpan</small></div><div class="row-value"><b>× ${x.quantity}</b><small>Jumlah</small></div></div>`).join('')||'<div class="empty">Inventori kosong.</div>'}</div>`}
function renderSalary(el){const rows=dashboardData.salaries;el.innerHTML=`<div class="welcome"><div><h1>Riwayat <em>Gaji.</em></h1><p>Catatan paycheck terbaru milik character.</p></div></div><div class="panel"><div class="panel-head"><h3>TRANSAKSI TERBARU</h3><span></span></div>${rows.map(x=>`<div class="salary-row"><div class="char-avatar">↗</div><div class="row-main"><b>${safe(x.info)}</b><small>${safe(x.date)}</small></div><div class="row-value"><b style="color:var(--green)">+ ${money(x.money)}</b><small>Diterima</small></div></div>`).join('')||'<div class="empty">Belum ada riwayat gaji.</div>'}</div>`}

function renderProgress(el){const skills=dashboardData.skills||[],fish=dashboardData.fish||[];el.innerHTML=`<div class="welcome"><div><h1>Skill & <em>Koleksi.</em></h1><p>Progress kemampuan dan hasil memancing seluruh Character IC.</p></div></div><div class="panel-grid"><div class="panel"><div class="panel-head"><h3>PLAYER SKILLS</h3><span>${skills.length} skill</span></div>${skills.map(s=>`<div class="inventory-row"><div class="char-avatar">★</div><div class="row-main"><b>${safe(s.name)}</b><small>Character ID #${s.owner} • EXP ${s.exp}</small></div><div class="row-value"><b>Level ${s.level}</b><small>Progress</small></div></div>`).join('')||'<div class="empty">Belum ada data skill.</div>'}</div><div class="panel"><div class="panel-head"><h3>FISH COLLECTION</h3><span>${fish.length} tangkapan</span></div>${fish.map(f=>`<div class="inventory-row"><div class="char-avatar">≈</div><div class="row-main"><b>${safe(f.name)}</b><small>Character ID #${f.owner}</small></div><div class="row-value"><b>${Number(f.weight).toLocaleString('id-ID')} gram</b><small>Berat</small></div></div>`).join('')||'<div class="empty">Belum ada koleksi ikan.</div>'}</div></div>`}
async function renderLifeHub(el){
  el.innerHTML='<div class="admin-loading"><span></span><b>Memuat Life Hub...</b></div>';
  try{const d=await api('/api/me/life');el.innerHTML=`<div class="welcome"><div><h1>Character <em>Life Hub.</em></h1><p>Identitas, lisensi, kebutuhan, komunikasi, akses kendaraan, dan usaha dalam satu tempat.</p></div></div><div class="life-character-tabs">${d.characters.map((c,i)=>`<button class="${i?'':'active'}" data-life-char="${c.reg_id}">${safe(c.username.replace('_',' '))}</button>`).join('')}</div>${d.characters.map((c,i)=>`<section class="life-character ${i?'hidden':''}" data-life-panel="${c.reg_id}"><div class="life-kpis"><article><small>LEVEL</small><b>${c.level}</b></article><article><small>PHONE</small><b>${c.phone||'-'}</b></article><article><small>GOLD</small><b>${c.gold}</b></article><article><small>HOPE COIN</small><b>${c.hopecoin}</b></article><article><small>PAYCHECK</small><b>${money(c.paycheck)}</b></article></div><div class="life-grid"><div class="life-card"><h3>IDENTITY</h3>${lifeRow('Full Name',c.username.replace('_',' '))}${lifeRow('Age',c.age)}${lifeRow('Origin',c.origin)}${lifeRow('Gender',c.gender?'Male':'Female')}${lifeRow('Height / Weight',`${c.height} cm / ${c.weight} kg`)}</div><div class="life-card"><h3>LICENSE & DOCUMENTS</h3>${lifeStatus('Identity Card',c.idcard)}${lifeStatus('Driving License',c.drivelic)}${lifeStatus('Character Story',c.charstory)}${lifeStatus('VIP Status',c.vip)}${lifeRow('Radio Frequency',c.wt||'-')}</div><div class="life-card"><h3>VITAL CONDITION</h3>${lifeMeter('Health',c.health)}${lifeMeter('Armour',c.armour)}${lifeMeter('Hunger',c.hunger)}${lifeMeter('Energy',c.energy)}${lifeMeter('Bladder',c.bladder)}</div><div class="life-card"><h3>EMPLOYMENT</h3>${lifeRow('Primary Job',`Job #${c.job}`)}${lifeRow('Secondary Job',`Job #${c.job2}`)}${lifeRow('Faction',`#${c.faction} • Rank ${c.factionrank}`)}${lifeRow('Family',`#${c.family} • Rank ${c.familyrank}`)}${lifeRow('Last Login',c.last_login)}</div><div class="life-card"><h3>LEGAL & MEDICAL</h3>${lifeStatus('Sick',c.sick,true)}${lifeStatus('Hospitalized',c.hospital,true)}${lifeStatus('Injured',c.injured,true)}${lifeStatus('Jailed',c.jail,true)}${lifeStatus('Arrested',c.arrest,true)}${lifeRow('Warnings',c.warn)}</div><div class="life-card"><h3>COMMUNICATION</h3>${lifeRow('Phone Number',c.phone||'-')}${lifeRow('Phone Credit',c.phonecredit)}${lifeRow('Contacts',d.contacts.filter(x=>x.ownerid===c.reg_id).length)}${lifeRow('Playlist',d.playlists.filter(x=>x.owner===c.reg_id).length)}${lifeRow('Vehicle Keys',d.keys.filter(x=>x.owner===c.reg_id).length)}</div></div><div class="life-collections"><div class="panel"><div class="panel-head"><h3>CONTACTS</h3></div>${d.contacts.filter(x=>x.ownerid===c.reg_id).map(x=>`<div class="inventory-row"><div class="char-avatar">☎</div><div class="row-main"><b>${safe(x.name)}</b><small>${x.number}</small></div></div>`).join('')||'<div class="empty">Kontak kosong.</div>'}</div><div class="panel"><div class="panel-head"><h3>VEHICLE ACCESS</h3></div>${d.keys.filter(x=>x.owner===c.reg_id).map(x=>`<div class="inventory-row"><div class="char-avatar">◇</div><div class="row-main"><b>${safe(x.plate||`Vehicle #${x.vehicle}`)}</b><small>Model ${x.model} • Fuel ${x.fuel}</small></div></div>`).join('')||'<div class="empty">Tidak memiliki kunci tambahan.</div>'}</div><div class="panel"><div class="panel-head"><h3>BUSINESS ASSETS</h3></div>${[...d.dealerships.filter(x=>x.ownerid===c.reg_id).map(x=>({name:x.name,info:`Dealership • Stock ${x.stock}`})),...d.workshops.filter(x=>x.ownerid===c.reg_id).map(x=>({name:x.name,info:`Workshop • Component ${x.component}`}))].map(x=>`<div class="inventory-row"><div class="char-avatar">▦</div><div class="row-main"><b>${safe(x.name)}</b><small>${safe(x.info)}</small></div></div>`).join('')||'<div class="empty">Belum ada aset usaha.</div>'}</div></div></section>`).join('')||'<div class="empty">Belum memiliki Character IC.</div>'}`;$$('[data-life-char]',el).forEach(b=>b.addEventListener('click',()=>{$$('[data-life-char]',el).forEach(x=>x.classList.remove('active'));$$('[data-life-panel]',el).forEach(x=>x.classList.add('hidden'));b.classList.add('active');$(`[data-life-panel="${b.dataset.lifeChar}"]`,el).classList.remove('hidden')}));
  }catch(error){el.innerHTML=`<div class="empty">${safe(error.message)}</div>`}
}
function lifeRow(label,value){return `<div class="life-row"><span>${safe(label)}</span><b>${safe(value??'-')}</b></div>`}function lifeStatus(label,value,danger=false){const active=Boolean(Number(value));return `<div class="life-row"><span>${safe(label)}</span><b class="life-state ${active?(danger?'danger':'active'):''}">${active?(danger?'YES':'ACTIVE'):'INACTIVE'}</b></div>`}function lifeMeter(label,value){const n=Math.max(0,Math.min(100,Number(value)||0));return `<div class="life-meter"><div><span>${label}</span><b>${Math.round(n)}%</b></div><i><em style="width:${n}%"></em></i></div>`}

async function renderRequestCS(el){
  el.innerHTML='<div class="admin-loading"><span></span><b>Memuat Request Character Story...</b></div>';
  try{const data=await api('/api/me/request-cs'),eligible=dashboardData.characters.filter(c=>!c.charstory&&!data.requests.some(r=>r.name===c.name));el.innerHTML=`<div class="welcome"><div><h1>Request <em>Character Story.</em></h1><p>Ajukan aktivasi Character Story langsung dari UCP.</p></div></div><div class="panel-grid"><div class="panel cs-guide"><span>✎</span><h3>PERSYARATAN REQUEST CS</h3><ol><li>Character harus berada pada UCP milikmu.</li><li>Satu UCP hanya boleh memiliki satu request aktif.</li><li>Staff akan memeriksa kelayakan dan riwayat character.</li><li>Status CS diaktifkan pada kolom <code>players.charstory</code>.</li></ol></div><div class="panel"><div class="panel-head"><h3>BUAT REQUEST</h3></div><form id="request-cs-form"><label>PILIH CHARACTER<select name="character" required><option value="">Pilih Character IC</option>${eligible.map(c=>`<option value="${safe(c.name)}">${safe(c.name)} — Level ${c.level}</option>`).join('')}</select></label><button class="btn btn-primary full" type="submit" ${eligible.length?'':'disabled'}>Kirim Request CS</button></form></div></div><div class="panel cs-status-panel"><div class="panel-head"><h3>REQUEST AKTIF</h3><span>${data.requests.length}</span></div>${data.requests.length?data.requests.map(r=>`<div class="cs-request-row"><span class="cs-pending">MENUNGGU REVIEW</span><div><b>${safe(r.name)}</b><small>UCP ${safe(r.user)} • Level ${r.level||'-'} • Character ID #${r.reg_id||'-'}</small></div><button data-cancel-cs="${safe(r.name)}">Batalkan</button></div>`).join(''):'<div class="empty">Tidak ada request yang menunggu.</div>'}</div>`;
    const form=$('#request-cs-form',el);form.addEventListener('submit',async e=>{e.preventDefault();const b=$('button',e.currentTarget);b.disabled=true;try{const result=await api('/api/me/request-cs',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast(result.message);renderRequestCS(el)}catch(error){toast(error.message);b.disabled=false}});$$('[data-cancel-cs]',el).forEach(b=>b.addEventListener('click',async()=>{try{await api(`/api/me/request-cs/${encodeURIComponent(b.dataset.cancelCs)}`,{method:'DELETE'});toast('Request dibatalkan');renderRequestCS(el)}catch(error){toast(error.message)}}));
  }catch(error){el.innerHTML=`<div class="empty">${safe(error.message)}</div>`}
}
function renderSettings(el) {
  const u=dashboardData.ucp;
  el.innerHTML=`<div class="welcome"><div><h1>Pengaturan <em>UCP.</em></h1><p>Kelola keamanan akun, PIN in-game, dan koneksi Discord.</p></div></div><div class="settings-pin"><span>PIN IN-GAME</span><b>${safe(u.gamePin||'-')}</b><button class="copy-game-pin" data-pin="${safe(u.gamePin||'')}">Salin</button></div><div class="panel-grid">
  <div class="panel"><div class="panel-head"><h3>GANTI PASSWORD</h3></div><form id="password-form"><label>PASSWORD SAAT INI<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>PASSWORD BARU<input name="newPassword" type="password" minlength="8" maxlength="72" autocomplete="new-password" required></label><button class="btn btn-primary" type="submit">Simpan Password</button></form></div>
  <div class="panel"><div class="panel-head"><h3>DISCORD USER ID</h3></div><p class="settings-note">ID saat ini: <code>${safe(u.discordId||'-')}</code>. Mengganti ID akan membatalkan verifikasi dan menghasilkan kode baru.</p><form id="discord-form"><label>DISCORD ID BARU<input name="discordId" inputmode="numeric" minlength="17" maxlength="20" required></label><label>PASSWORD UCP<input name="currentPassword" type="password" autocomplete="current-password" required></label><button class="btn btn-primary" type="submit">Ganti Discord ID</button></form></div></div><div id="settings-message"></div>`;
  $('#password-form',el).addEventListener('submit',async e=>{e.preventDefault();const b=$('button',e.currentTarget);b.disabled=true;try{const result=await api('/api/me/password',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});$('#settings-message').innerHTML=`<div class="alert success">${safe(result.message)}</div>`;e.currentTarget.reset()}catch(error){$('#settings-message').innerHTML=`<div class="alert">${safe(error.message)}</div>`}finally{b.disabled=false}});
  $('#discord-form',el).addEventListener('submit',async e=>{e.preventDefault();const b=$('button',e.currentTarget);b.disabled=true;try{const result=await api('/api/me/discord',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});$('#settings-message').innerHTML=`<div class="alert success">${safe(result.message)} Kode: <b>${safe(result.verifyCode)}</b></div>`;dashboardData.ucp.discordId=new FormData(e.currentTarget).get('discordId');dashboardData.ucp.gamePin=result.verifyCode;dashboardData.ucp.verified=false;e.currentTarget.reset()}catch(error){$('#settings-message').innerHTML=`<div class="alert">${safe(error.message)}</div>`}finally{b.disabled=false}});
}

function adminRows(items, render, empty='Tidak ada data') { return items.length ? items.map(render).join('') : `<div class="admin-empty">${empty}</div>`; }
async function renderAdmin(el, query = '') {
  el.innerHTML='<div class="admin-loading"><span></span><b>Menyiapkan Command Center...</b><small>Membaca data Hope City</small></div>';
  let data,staffData,insights,csData,commandData,payData;
  try {[data,staffData,insights,csData,commandData,payData]=await Promise.all([api('/api/admin/overview'+(query?`?q=${encodeURIComponent(query)}`:'')),api('/api/admin/staff'),api('/api/admin/insights'),api('/api/admin/request-cs'),api('/api/admin/command-logs'),api('/api/admin/pay-logs')]);}
  catch(error){el.innerHTML=`<div class="empty">${safe(error.message)}</div>`;return}
  let grantData={characters:[],items:[],vehicles:[]};if(data.adminLevel>=5){try{grantData=await api('/api/admin/grant/options')}catch(error){toast(error.message)}}
  const rawCounts=data.counts||{},c=Object.fromEntries(['ucps','pending','characters','admins','vehicles','houses','businesses','families'].map(k=>[k,Number(rawCounts[k]||0)])),e=insights.economy||{};
  el.innerHTML=`<div class="admin-hero"><div><span>HOPE PRIDE MANAGEMENT</span><h1>Administrator <em>Control.</em></h1><p>Command center level ${data.adminLevel} • sinkron langsung dengan database</p></div><div class="admin-hero-status"><i></i><b>SYSTEM OPERATIONAL</b><small>${insights.database.tables} tabel • ${insights.database.size_mb} MB</small></div></div>
  <div class="admin-kpis"><article><span>◉</span><div><small>TOTAL UCP</small><b>${c.ucps}</b><em>${c.pending} pending</em></div></article><article><span>♙</span><div><small>CHARACTERS</small><b>${c.characters}</b><em>${c.admins} admin</em></div></article><article><span>◇</span><div><small>CITY ASSETS</small><b>${c.vehicles+c.houses}</b><em>${c.vehicles} vehicle</em></div></article><article><span>▦</span><div><small>ECONOMY</small><b>${c.businesses}</b><em>${c.families} families</em></div></article></div>
  <nav class="admin-tabs"><button class="active" data-admin-tab="overview">Overview</button><button data-admin-tab="users">UCP & Player</button><button data-admin-tab="economy">Economy</button><button data-admin-tab="assets">City Assets</button><button data-admin-tab="security">Security</button><button data-admin-tab="monitoring">CMD & Pay Logs</button><button data-admin-tab="requests">Request CS</button><button data-admin-tab="tools">Create Tools</button></nav>
  <section class="admin-section active" data-admin-section="overview"><div class="admin-top-grid"><div class="admin-box"><div class="admin-box-head"><div><small>TEAM MANAGEMENT</small><h3>Staff & Administrator</h3></div><span>${staffData.total} STAFF</span></div><div class="staff-list">${adminRows(staffData.staff,s=>`<div class="staff-card"><span>${safe(s.username[0])}</span><div><b>${safe(s.username)}</b><small>${s.admin?`Administrator Lv. ${s.admin}`:`Helper Lv. ${s.helper}`} • ${safe(s.ucp)}</small></div><i class="${s.verifystatus?'online':''}"></i></div>`,'Belum ada staff')}</div></div><div class="admin-backup"><span class="backup-icon">⇩</span><small>SECURE BACKUP</small><h3>Database Protection</h3><p>Download snapshot SQL atau export daftar UCP untuk laporan.</p><a href="/api/admin/backup" download>Download SQL Backup</a><a class="secondary" href="/api/admin/export/ucp.csv" download>Export UCP CSV</a><em>Maksimal 5 backup per jam</em></div></div>
  <div class="admin-insight-grid three"><div class="admin-box"><div class="admin-box-head"><h3>Recent Staff Activity</h3><span>LIVE LOG</span></div><div class="compact-list">${adminRows(insights.logs.slice(0,6),x=>`<div><b>${safe(x.command)}</b><span>${safe(x.admin)} → ${safe(x.player)}</span><small>${formatUnix(x.time)}</small></div>`)}</div></div><div class="admin-box"><div class="admin-box-head"><h3>VIP Players</h3><span>${insights.vips.length}</span></div><div class="compact-list">${adminRows(insights.vips.slice(0,6),x=>`<div><b>${safe(x.username)}</b><span>VIP Level ${x.vip}</span><small>${safe(x.ucp)}</small></div>`)}</div></div><div class="admin-box"><div class="admin-box-head"><h3>Top Inventory Items</h3></div><div class="compact-list">${adminRows(insights.items.slice(0,6),x=>`<div><b>${safe(x.item)}</b><span>${Number(x.quantity).toLocaleString('id-ID')} unit</span><small>${x.owners} owner</small></div>`)}</div></div></div></section>
  <section class="admin-section" data-admin-section="users"><div class="admin-box"><div class="admin-box-head users-head"><div><small>ACCOUNT DIRECTORY</small><h3>UCP Management</h3></div><form id="admin-search" class="admin-search"><input name="q" value="${safe(query)}" placeholder="Username atau Discord ID"><button type="submit">Search</button></form></div><div class="admin-table"><div class="admin-table-head"><span>UCP</span><span>DISCORD ID</span><span>CHAR</span><span>STATUS</span><span>ACTION</span></div>${adminRows(data.accounts,u=>`<div class="admin-account"><div><b>${safe(u.username)}</b><small>#${u.id} • Admin ${Math.max(Number(u.admin),Number(u.game_admin))}</small></div><code>${safe(u.discordid||'-')}</code><span>${u.characters}</span><span class="state ${u.verifystatus?'ok':'pending'}">${u.verifystatus?'VERIFIED':'PENDING'}</span><div class="admin-actions"><button class="admin-toggle" data-action="verify" data-id="${u.id}" data-state="${u.verifystatus?1:0}">${u.verifystatus?'Unverify':'Verify'}</button><button class="admin-toggle" data-action="reset" data-id="${u.id}">Reset PIN</button><button class="admin-toggle" data-action="discord" data-id="${u.id}">Discord</button></div></div>`)}</div></div></section>
  <section class="admin-section" data-admin-section="economy"><div class="economy-strip">${[['Server Treasury',e.servermoney],['Material',e.material],['Component',e.component],['Gas Oil',e.gasoil],['Product',e.product],['Food Stock',e.food],['Hope Coin',e.hopecoin]].map(([k,v])=>`<article><small>${k}</small><b>${Number(v||0).toLocaleString('id-ID')}</b></article>`).join('')}</div><div class="admin-insight-grid three"><div class="admin-box"><div class="admin-box-head"><h3>Job Distribution</h3></div><div class="distribution">${adminRows(insights.jobs,x=>`<div><span>Job #${x.job}</span><i style="--value:${Math.min(100,x.total)}%"></i><b>${x.total}</b></div>`)}</div></div><div class="admin-box"><div class="admin-box-head"><h3>Faction Distribution</h3></div><div class="distribution">${adminRows(insights.factions,x=>`<div><span>Faction #${x.faction}</span><i style="--value:${Math.min(100,x.total)}%"></i><b>${x.total}</b></div>`)}</div></div><div class="admin-box"><div class="admin-box-head"><h3>Market Prices</h3></div><div class="price-list">${[['Material',e.materialprice],['Component',e.componentprice],['Gas Oil',e.gasoilprice],['Product',e.productprice],['Food',e.foodprice],['Hope Coin',e.hopecoinprice]].map(([k,v])=>`<div><span>${k}</span><b>${money(v)}</b></div>`).join('')}</div></div></div></section>
  <section class="admin-section" data-admin-section="assets"><div class="admin-insight-grid two"><div class="admin-box"><div class="admin-box-head"><h3>Businesses</h3><span>${insights.businesses.length} latest</span></div><div class="asset-admin-list">${adminRows(insights.businesses,b=>`<div><span>▦</span><div><b>${safe(b.name)}</b><small>#${b.id} • ${safe(b.owner)} • Type ${b.type}</small></div><em>${money(b.price)}</em></div>`)}</div></div><div class="admin-box"><div class="admin-box-head"><h3>Families</h3><span>${insights.families.length}</span></div><div class="asset-admin-list">${adminRows(insights.families,f=>`<div><span>◇</span><div><b>${safe(f.name)}</b><small>Leader ${safe(f.leader)} • #${f.id}</small></div><em>${money(f.money)}</em></div>`)}</div></div><div class="admin-box"><div class="admin-box-head"><h3>Workshops</h3><span>${insights.workshops.length}</span></div><div class="asset-admin-list">${adminRows(insights.workshops,w=>`<div><span>⚙</span><div><b>${safe(w.name||`Workshop #${w.id}`)}</b><small>${safe(w.owner)} • Component ${w.component}</small></div><em>${money(w.price)}</em></div>`)}</div></div><div class="admin-box"><div class="admin-box-head"><h3>Active Vouchers</h3><span>${insights.vouchers.length}</span></div><div class="asset-admin-list">${adminRows(insights.vouchers,v=>`<div><span>✦</span><div><b>${safe(v.code)}</b><small>VIP ${v.vip} • Gold ${v.gold}</small></div><em>${formatUnix(v.expired)}</em></div>`)}</div></div></div></section>
  <section class="admin-section" data-admin-section="security"><div class="admin-insight-grid two"><div class="admin-box danger-box"><div class="admin-box-head"><h3>Blacklist</h3><span>${insights.blacklist.length}</span></div><div class="security-list">${adminRows(insights.blacklist,x=>`<div><span>!</span><div><b>${safe(x.player)}</b><small>${safe(x.reason)} • by ${safe(x.bannedby)}</small></div></div>`,'Blacklist kosong')}</div></div><div class="admin-box"><div class="admin-box-head"><h3>Warn & Jail Monitor</h3><span>${insights.sanctions.length}</span></div><div class="security-list">${adminRows(insights.sanctions,x=>`<div><span>§</span><div><b>${safe(x.username)}</b><small>Warn ${x.warn} • Jail ${x.jail?'YES':'NO'} • ${x.jail_time}s</small></div></div>`,'Tidak ada sanction')}</div></div><div class="admin-box full-span"><div class="admin-box-head"><h3>Complete Staff Audit</h3><span>LAST 15</span></div><div class="audit-table">${adminRows(insights.logs,x=>`<div><b>${safe(x.command)}</b><span>${safe(x.admin)}</span><span>${safe(x.player)}</span><code>${safe(x.str)}</code><time>${formatUnix(x.time)}</time></div>`)}</div></div></div></section>
  <section class="admin-section" data-admin-section="monitoring"><div class="monitor-kpis"><article><small>CMD LOGS</small><b>${commandData.summary.total}</b><span>${commandData.summary.admins} admin</span></article><article><small>PAY TRANSFERS</small><b>${payData.summary.transfers}</b><span>${money(payData.summary.volume)}</span></article><article class="risk"><small>HIGH VALUE</small><b>${payData.summary.high_value||0}</b><span>≥ ${money(payData.threshold)}</span></article><article><small>LARGEST PAY</small><b>${money(payData.summary.largest)}</b><span>single transfer</span></article></div><div class="log-toolbar"><div><b>ABUSE MONITORING</b><small>Penanda risiko membantu investigasi; bukan bukti otomatis RTM.</small></div><input id="log-filter" placeholder="Filter admin, command, atau player..."></div><div class="admin-box"><div class="admin-box-head"><h3>Administrator Command Logs</h3><span>LAST ${commandData.logs.length}</span></div><div class="cmd-log-table" id="cmd-log-table">${adminRows(commandData.logs,x=>`<div data-log-search="${safe(`${x.command} ${x.admin} ${x.player} ${x.str}`.toLowerCase())}"><time>${formatUnix(x.time)}</time><b>${safe(x.command)}</b><span>${safe(x.admin)}</span><span>→ ${safe(x.player)}</span><code>${safe(x.str)}</code></div>`)}</div></div><div class="admin-box pay-box"><div class="admin-box-head"><h3>Player Payment Logs</h3><span>RTM WATCH</span></div><div class="pay-log-table">${adminRows(payData.logs,x=>`<div class="${x.risk!=='NORMAL'?'flagged':''}"><time>${formatUnix(x.time)}</time><span><b>${safe(x.player)}</b><small>ID #${x.playerid}</small></span><i>→</i><span><b>${safe(x.toplayer)}</b><small>ID #${x.toplayerid}</small></span><strong>${money(x.ammount)}</strong><em class="risk-${x.risk.toLowerCase()}">${x.risk.replace('_',' ')}</em></div>`)}</div></div><div class="admin-box"><div class="admin-box-head"><h3>Repeated Transfer Pairs</h3><span>REVIEW QUEUE</span></div><div class="repeat-grid">${adminRows(payData.repeated,x=>`<div><b>${safe(x.player)} → ${safe(x.toplayer)}</b><span>${x.transfers} transaksi</span><strong>${money(x.volume)}</strong></div>`,'Tidak ada pola transfer berulang.')}</div></div></section>
  <section class="admin-section" data-admin-section="requests"><div class="admin-box"><div class="admin-box-head"><div><small>CHARACTER STORY</small><h3>Pending Request CS</h3></div><span>${csData.total} WAITING</span></div><div class="cs-admin-grid">${adminRows(csData.requests,r=>`<article><div class="cs-avatar">${safe(r.name?.[0]||'?')}</div><div><b>${safe(r.name)}</b><small>UCP ${safe(r.user)} • ID #${r.reg_id||'-'} • Level ${r.level||'-'} • ${r.hours||0} jam</small><em>Last login: ${safe(r.last_login||'-')}</em></div><div class="cs-actions"><button data-cs-decision="approve" data-character="${safe(r.name)}">Approve</button><button data-cs-decision="reject" data-character="${safe(r.name)}">Reject</button></div></article>`,'Tidak ada Request CS yang menunggu.')}</div></div></section>
  <section class="admin-section" data-admin-section="tools"><div class="admin-create-grid"><form class="admin-box admin-create" id="create-business"><div class="admin-box-head"><h3>+ Tambah Bisnis</h3></div><label>NAMA<input name="name" maxlength="40" required></label><div class="form-two"><label>JENIS<select name="type"><option value="1">Warung / Restoran</option><option value="2">Toko Umum</option><option value="3">Toko Pakaian</option><option value="4">Usaha Khusus</option></select></label><label>HARGA<input name="price" type="number" min="0" value="500000"></label></div><div class="form-three"><label>POS X<input name="x" type="number" step="any" value="0"></label><label>POS Y<input name="y" type="number" step="any" value="0"></label><label>POS Z<input name="z" type="number" step="any" value="0"></label></div><button class="btn btn-primary" type="submit">Tambahkan</button></form><form class="admin-box admin-create" id="create-voucher"><div class="admin-box-head"><h3>+ Buat Voucher</h3></div><label>KODE<input name="code" maxlength="32" required></label><div class="form-two"><label>VIP<input name="vip" type="number" min="0" max="3" value="0"></label><label>VIP HARI<input name="vipDays" type="number" min="0" max="365" value="0"></label></div><div class="form-two"><label>GOLD<input name="gold" type="number" min="0" value="0"></label><label>EXPIRED<input name="expiresDays" type="number" min="1" max="365" value="30"></label></div><button class="btn btn-primary" type="submit">Terbitkan</button></form><form class="admin-box admin-create" id="create-family"><div class="admin-box-head"><h3>+ Buat Family</h3></div><label>NAMA<input name="name" maxlength="50" required></label><label>LEADER IC<input name="leader" maxlength="50" required></label><label>MOTD<input name="motd" maxlength="100"></label><label>WARNA<input name="color" type="number" value="0"></label><button class="btn btn-primary" type="submit">Buat Family</button></form></div>${data.adminLevel>=5?`<div class="grant-center"><div class="grant-header"><div><small>ADMIN LEVEL 5+ ONLY</small><h3>Secure Grant Center</h3><p>Semua pemberian tercatat otomatis ke Staff Audit Log.</p></div><span>LEVEL ${data.adminLevel}</span></div><datalist id="grant-characters">${grantData.characters.map(c=>`<option value="${safe(c.username)}">${safe(c.ucp)} • Level ${c.level}</option>`).join('')}</datalist><datalist id="grant-items">${grantData.items.map(i=>`<option value="${safe(i)}"></option>`).join('')}</datalist><div class="grant-grid"><form class="grant-form" data-grant="money"><span>＄</span><h4>Give Money</h4><label>CHARACTER<input name="character" list="grant-characters" required></label><div class="form-two"><label>ACCOUNT<select name="account"><option value="money">Cash</option><option value="bank">Bank</option><option value="gold">Gold</option><option value="hopecoin">Hope Coin</option></select></label><label>AMOUNT<input name="amount" type="number" min="1" max="1000000000" required></label></div><button type="submit">Give Balance</button></form><form class="grant-form" data-grant="item"><span>▦</span><h4>Give Item</h4><label>CHARACTER<input name="character" list="grant-characters" required></label><label>ITEM<input name="item" list="grant-items" maxlength="32" required></label><label>QUANTITY<input name="quantity" type="number" min="1" max="100000" required></label><button type="submit">Give Item</button></form><form class="grant-form" data-grant="vehicle"><span>◇</span><h4>Give Vehicle</h4><label>CHARACTER<input name="character" list="grant-characters" required></label><div class="form-two"><label>MODEL<select name="model">${grantData.vehicles.map(v=>`<option value="${v.model}">${v.model} — ${safe(v.name)}</option>`).join('')}</select></label><label>PRICE<input name="price" type="number" min="0" value="0"></label></div><div class="form-two"><label>COLOR 1<input name="color1" type="number" min="0" max="255" value="0"></label><label>COLOR 2<input name="color2" type="number" min="0" max="255" value="0"></label></div><button type="submit">Give Vehicle</button></form><form class="grant-form org-form" id="organization-form"><span>⚑</span><h4>Set Organization</h4><label>CHARACTER<input name="character" list="grant-characters" required></label><div class="form-two"><label>TYPE<select name="mode"><option value="faction">Faction</option><option value="family">Family</option></select></label><label>ID<input name="id" type="number" min="-1" max="255" required></label></div><div class="form-two"><label>RANK<input name="rank" type="number" min="0" max="255" value="0"></label><label>LEADER<select name="leader"><option value="">No</option><option value="1">Yes</option></select></label></div><button type="submit">Update Organization</button></form></div></div>`:'<div class="level-locked">Grant Center membutuhkan Administrator Level 5 atau lebih tinggi.</div>'}</section>`;
  $$('.admin-tabs button',el).forEach(tab=>tab.addEventListener('click',()=>{$$('.admin-tabs button',el).forEach(x=>x.classList.remove('active'));$$('[data-admin-section]',el).forEach(x=>x.classList.remove('active'));tab.classList.add('active');$(`[data-admin-section="${tab.dataset.adminTab}"]`,el).classList.add('active')}));
  const logFilter=$('#log-filter',el);logFilter.addEventListener('input',()=>{$$('[data-log-search]',el).forEach(row=>row.classList.toggle('hidden',!row.dataset.logSearch.includes(logFilter.value.toLowerCase().trim())))});
  $$('[data-cs-decision]',el).forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{await api(`/api/admin/request-cs/${encodeURIComponent(button.dataset.character)}/decision`,{method:'POST',body:JSON.stringify({action:button.dataset.csDecision})});toast(`Request CS ${button.dataset.csDecision==='approve'?'disetujui':'ditolak'}`);await renderAdmin(el);$('[data-admin-tab="requests"]',el)?.click()}catch(error){toast(error.message);button.disabled=false}}));
  const search=$('#admin-search',el);search.addEventListener('submit',e=>{e.preventDefault();renderAdmin(el,new FormData(e.currentTarget).get('q').trim()).then(()=>{$('[data-admin-tab="users"]',el)?.click()})});
  [['#create-business','/api/admin/businesses'],['#create-voucher','/api/admin/vouchers'],['#create-family','/api/admin/families']].forEach(([selector,url])=>$(selector,el).addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type=submit]',e.currentTarget),original=button.textContent;button.disabled=true;button.textContent='Menyimpan...';try{const result=await api(url,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast(result.code?`Voucher ${result.code} dibuat`:'Data berhasil ditambahkan');e.currentTarget.reset();if(url.includes('businesses'))loadBusinesses()}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent=original}}));
  $$('.grant-form[data-grant]',el).forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const button=$('button[type=submit]',form),original=button.textContent;if(!confirm(`Konfirmasi ${original} ke ${new FormData(form).get('character')}?`))return;button.disabled=true;button.textContent='Processing...';try{const result=await api(`/api/admin/grant/${form.dataset.grant}`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast(result.message);form.reset()}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent=original}}));
  const orgForm=$('#organization-form',el);if(orgForm)orgForm.addEventListener('submit',async e=>{e.preventDefault();const payload=Object.fromEntries(new FormData(orgForm));if(!confirm(`Update ${payload.character} ke ${payload.mode} #${payload.id}?`))return;const button=$('button',orgForm);button.disabled=true;try{const result=await api('/api/admin/manage/organization',{method:'POST',body:JSON.stringify(payload)});toast(result.message);orgForm.reset()}catch(error){toast(error.message)}finally{button.disabled=false}});
  $$('.admin-toggle',el).forEach(button=>button.addEventListener('click',async()=>{button.disabled=true;try{if(button.dataset.action==='verify'){await api(`/api/admin/ucp/${button.dataset.id}/verification`,{method:'PATCH',body:JSON.stringify({verified:button.dataset.state!=='1'})});toast('Status verifikasi diperbarui')}if(button.dataset.action==='reset'){const r=await api(`/api/admin/ucp/${button.dataset.id}/reset-verification`,{method:'POST'});alert(`PIN baru: ${r.verifyCode}`)}if(button.dataset.action==='discord'){const id=prompt('Discord User ID baru:');if(!id){button.disabled=false;return}const r=await api(`/api/admin/ucp/${button.dataset.id}/discord`,{method:'PATCH',body:JSON.stringify({discordId:id.trim()})});alert(`Discord diperbarui. PIN: ${r.verifyCode}`)}await renderAdmin(el,query);$('[data-admin-tab="users"]',el)?.click()}catch(error){toast(error.message);button.disabled=false}}));
}
function formatUnix(value){const n=Number(value);if(!n)return'-';return new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'2-digit'}).format(new Date(n*1000))}

let forumCategories=[],forumCategory=0;
async function loadForumCategories(){
  const host=$('#forum-category-list');
  try{const data=await api('/api/forum/categories');forumCategories=data.categories;host.innerHTML=data.categories.map(c=>`<button data-forum-category="${c.id}"><span>${safe(c.icon)}</span><b>${safe(c.name)}</b><small>${c.topics}</small></button>`).join('');$('#topic-category').innerHTML=data.categories.map(c=>`<option value="${c.id}">${safe(c.name)}</option>`).join('');$$('[data-forum-category]',host).forEach(b=>b.addEventListener('click',()=>{$$('[data-forum-category]').forEach(x=>x.classList.remove('active'));b.classList.add('active');forumCategory=Number(b.dataset.forumCategory);loadForumTopics()}));await loadForumTopics()}catch(error){host.innerHTML='';$('#forum-content-list').innerHTML=`<div class="forum-empty">${safe(error.message)}</div>`}
}
async function loadForumTopics(){
  const host=$('#forum-content-list'),q=$('#forum-search-input').value.trim();$('#forum-back').classList.add('hidden');host.innerHTML='<div class="forum-empty">Memuat topic...</div>';
  try{const data=await api(`/api/forum/topics?category=${forumCategory}&q=${encodeURIComponent(q)}`);host.innerHTML=data.topics.length?`<div class="topic-table-head"><span>TOPIC</span><span>REPLIES</span><span>VIEWS</span><span>UPDATED</span></div>`+data.topics.map(t=>`<button class="topic-row" data-topic-id="${t.id}"><span class="topic-symbol">${t.pinned?'◆':t.locked?'⌕':'◯'}</span><span class="topic-title"><b>${safe(t.title)}</b><small>${safe(t.category_name)} • oleh ${safe(t.author_ucp)}</small></span><span>${t.replies}</span><span>${t.views}</span><time>${formatForumDate(t.updated_at)}</time></button>`).join(''):'<div class="forum-empty">Belum ada topic. Jadilah yang pertama berdiskusi.</div>';$$('[data-topic-id]',host).forEach(b=>b.addEventListener('click',()=>openForumTopic(b.dataset.topicId)))}catch(error){host.innerHTML=`<div class="forum-empty">${safe(error.message)}</div>`}
}
function formatForumDate(value){if(!value)return'-';const d=new Date(value);return Number.isNaN(d.getTime())?safe(value):new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'short',year:'numeric'}).format(d)}
async function openForumTopic(id){
  const host=$('#forum-content-list');host.innerHTML='<div class="forum-empty">Membuka topic...</div>';
  try{const data=await api(`/api/forum/topics/${id}`),t=data.topic,isAdmin=Boolean(dashboardData?.ucp?.isAdmin);$('#forum-back').classList.remove('hidden');host.innerHTML=`<article class="topic-detail"><div class="topic-detail-head"><span>${safe(t.category_name)}</span><h3>${safe(t.title)}</h3><small>Oleh <b>${safe(t.author_ucp)}</b> • ${formatForumDate(t.created_at)} • ${t.views} views</small></div><div class="forum-post original"><div class="post-author"><span>${safe(t.author_ucp[0].toUpperCase())}</span><b>${safe(t.author_ucp)}</b><small>Topic Author</small></div><div class="post-body">${safe(t.content).replace(/\n/g,'<br>')}</div></div>${data.posts.map(p=>`<div class="forum-post"><div class="post-author"><span>${safe(p.author_ucp[0].toUpperCase())}</span><b>${safe(p.author_ucp)}</b><small>${formatForumDate(p.created_at)}</small></div><div class="post-body">${safe(p.content).replace(/\n/g,'<br>')}</div></div>`).join('')}${t.locked&&!isAdmin?'<div class="forum-locked">Topic ini telah dikunci oleh administrator.</div>':`<form class="reply-form" id="reply-form"><textarea name="content" maxlength="5000" placeholder="Tulis balasan..." required></textarea><button class="btn btn-primary" type="submit">Kirim Balasan</button></form>`}${isAdmin?`<div class="moderation-bar"><b>MODERATION</b><button data-moderate="pin">${t.pinned?'Lepas Pin':'Pin Topic'}</button><button data-moderate="lock">${t.locked?'Buka Topic':'Kunci Topic'}</button></div>`:''}</article>`;
    const reply=$('#reply-form',host);if(reply)reply.addEventListener('submit',async e=>{e.preventDefault();if(!dashboardData)return openAuth('login');const b=$('button',e.currentTarget);b.disabled=true;try{await api(`/api/forum/topics/${id}/posts`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});openForumTopic(id)}catch(error){toast(error.message);b.disabled=false}});
    $$('[data-moderate]',host).forEach(b=>b.addEventListener('click',async()=>{await api(`/api/forum/topics/${id}/moderation`,{method:'PATCH',body:JSON.stringify({pinned:b.dataset.moderate==='pin'?!t.pinned:t.pinned,locked:b.dataset.moderate==='lock'?!t.locked:t.locked})});openForumTopic(id)}));
  }catch(error){host.innerHTML=`<div class="forum-empty">${safe(error.message)}</div>`}
}

let cityExplorerData=null,explorerView='houses';
async function loadCityExplorer(){try{cityExplorerData=await api('/api/city/explorer');renderCityExplorer()}catch(error){$('#explorer-content').innerHTML=`<div class="directory-loading offline">${safe(error.message)}</div>`}}
function renderCityExplorer(){if(!cityExplorerData)return;const host=$('#explorer-content'),d=cityExplorerData;if(explorerView==='services'){host.innerHTML=`<div class="service-grid">${Object.entries(d.services).map(([name,count])=>`<article><span>${{atms:'$',parks:'P',modshops:'⚙',lockers:'▣',doors:'↗',gates:'⌁'}[name]||'•'}</span><b>${count}</b><small>${name.toUpperCase()}</small></article>`).join('')}</div>`;return}const configs={houses:{icon:'⌂',title:x=>x.address,meta:x=>`${x.owner==='-'?'For Sale':`Owner ${x.owner}`} • Type ${x.type}`,value:x=>money(x.price)},dealerships:{icon:'◇',title:x=>x.name,meta:x=>`${x.ownername==='-'?'Government':x.ownername} • Stock ${x.stock}`,value:x=>x.status?'OPEN':'CLOSED'},workshops:{icon:'⚙',title:x=>x.name||`Workshop #${x.id}`,meta:x=>`${x.owner||'Government'} • Component ${x.component}`,value:x=>money(x.price)},gasStations:{icon:'⛽',title:x=>`Fuel Point #${x.id}`,meta:x=>`Position ${Number(x.posx).toFixed(0)}, ${Number(x.posy).toFixed(0)}`,value:x=>`${x.stock.toLocaleString('id-ID')} L`},zones:{icon:'⌖',title:x=>x.name,meta:x=>`Zone Type ${x.type} • ID #${x.id}`,value:x=>'ACTIVE'}};const cfg=configs[explorerView],items=d[explorerView]||[];host.innerHTML=`<div class="explorer-grid">${items.map(x=>`<article><span>${cfg.icon}</span><div><h4>${safe(cfg.title(x))}</h4><p>${safe(cfg.meta(x))}</p></div><b>${safe(cfg.value(x))}</b></article>`).join('')||'<div class="directory-loading">Belum ada data.</div>'}</div>`}

let businessType=0, businessTimer;
async function loadBusinesses(){
  const grid=$('#business-grid'); if(!grid)return;
  grid.innerHTML='<div class="directory-loading">Memuat usaha Hope City...</div>';
  const q=$('#business-search').value.trim();
  try{const data=await api(`/api/city/businesses?type=${businessType}&q=${encodeURIComponent(q)}`);const labels=['','Warung & Restoran','Toko Umum','Toko Pakaian','Usaha Khusus'];const icons=['','☕','▦','♙','◇'];grid.innerHTML=data.businesses.length?data.businesses.map((b,i)=>`<article class="business-card" style="--delay:${Math.min(i,12)*45}ms"><div class="business-card-top"><span class="business-icon">${icons[b.type]||'▤'}</span><span class="business-state ${b.locked?'closed':'open'}">${b.locked?'TUTUP':'BUKA'}</span></div><small>${safe(labels[b.type]||`BISNIS ${b.type}`)}</small><h3>${safe(b.name)}</h3><p>${b.owner==='-'?'Milik Pemerintah':`Pemilik • ${safe(b.owner.replace('_',' '))}`}</p><div class="business-meta"><span>Stok <b>${b.prod}</b></span><span>Nilai <b>${money(b.price)}</b></span></div></article>`).join(''):'<div class="directory-loading">Tidak ada bisnis yang cocok.</div>'}catch(error){grid.innerHTML=`<div class="directory-loading offline">${safe(error.message)}</div>`}
}

async function init() {
  const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')}),{threshold:.08}); $$('.reveal').forEach(e=>observer.observe(e));
  window.addEventListener('scroll',()=>$('.nav').classList.toggle('sticky',window.scrollY>80),{passive:true});
  $('.mobile-menu').addEventListener('click',()=>$('.nav-links').classList.toggle('mobile-open'));
  $$('.nav-links a').forEach(a=>a.addEventListener('click',()=>$('.nav-links').classList.remove('mobile-open')));
  $$('[data-business-type]').forEach(b=>b.addEventListener('click',()=>{$$('[data-business-type]').forEach(x=>x.classList.remove('active'));b.classList.add('active');businessType=Number(b.dataset.businessType);loadBusinesses()}));
  $('#business-search').addEventListener('input',()=>{clearTimeout(businessTimer);businessTimer=setTimeout(loadBusinesses,280)});
  loadBusinesses();
  $$('[data-explorer]').forEach(b=>b.addEventListener('click',()=>{$$('[data-explorer]').forEach(x=>x.classList.remove('active'));b.classList.add('active');explorerView=b.dataset.explorer;renderCityExplorer()}));loadCityExplorer();
  $('[data-forum-category="0"]').addEventListener('click',e=>{$$('[data-forum-category]').forEach(x=>x.classList.remove('active'));e.currentTarget.classList.add('active');forumCategory=0;loadForumTopics()});
  loadForumCategories();
  $('#forum-search-button').addEventListener('click',loadForumTopics);$('#forum-search-input').addEventListener('keydown',e=>{if(e.key==='Enter')loadForumTopics()});$('#forum-back').addEventListener('click',loadForumTopics);
  $('#new-topic-button').addEventListener('click',()=>{if(!dashboardData)return openAuth('login');$('#forum-compose').classList.remove('hidden')});$('.compose-close').addEventListener('click',()=>$('#forum-compose').classList.add('hidden'));$('#forum-compose').addEventListener('click',e=>{if(e.target===$('#forum-compose'))$('#forum-compose').classList.add('hidden')});
  $('#new-topic-form').addEventListener('submit',async e=>{e.preventDefault();const b=$('button',e.currentTarget);b.disabled=true;try{const result=await api('/api/forum/topics',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});$('#forum-compose').classList.add('hidden');e.currentTarget.reset();await loadForumCategories();openForumTopic(result.id);toast('Topic berhasil dipublikasikan')}catch(error){toast(error.message)}finally{b.disabled=false}});
  setInterval(()=>{$('#server-clock').textContent=new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(new Date())+' WIB'},1000);
  try { const s=await api('/api/public'); $('#stat-players').textContent=s.players; $('#stat-vehicles').textContent=s.vehicles; $('#stat-properties').textContent=s.properties; $('#stat-ucps').textContent=s.ucps; $('#stat-online').textContent=s.online; $('#server-status-text').textContent=s.database==='live'?'TERHUBUNG':'DATABASE OFFLINE'; $('#server-status-text').style.color=s.database==='live'?'var(--green)':'#e66f6f'; $('#portal-online').textContent=s.online;$('#portal-characters').textContent=s.players;$('#portal-vehicles').textContent=s.vehicles;$('#portal-properties').textContent=s.properties;$('#forum-businesses').textContent=s.businesses;$('#forum-characters').textContent=s.players;$('#forum-families').textContent=s.families;$('#portal-db-dot').classList.toggle('offline',s.database!=='live');if(s.serverAddress){$('#server-ip').textContent=s.serverAddress;$('#notice-server-ip').textContent=s.serverAddress;$('.copy-btn').dataset.copy=s.serverAddress;$('.notice-copy').dataset.copy=s.serverAddress}else{$('#server-ip').textContent='Belum dikonfigurasi';$('.copy-btn').classList.add('hidden');$('.notice-copy').classList.add('hidden')} if(s.discordInvite){$('#discord-link').href=s.discordInvite}else{$('#discord-link').removeAttribute('href')} } catch { $('#server-status-text').textContent='TIDAK TERSEDIA'; }
  try { const activeSession=await api('/api/session'); if(activeSession.authenticated){dashboardData=await api('/api/me');syncAuthUI(true)}else syncAuthUI(false) } catch { syncAuthUI(false) }
  handleRoute(false);
}
init();
